<?phpsession_start();require_once "db.php";// Admin securityif (!isset($_SESSION['admin_id'])) {    header("Location: index.php");    exit();}$message = "";if (empty($_SESSION['subject_csrf'])) {    $_SESSION['subject_csrf'] = bin2hex(random_bytes(32));}// DELETE SUBJECTif (isset($_POST['delete_subject'])) {    if (!hash_equals($_SESSION['subject_csrf'], $_POST['csrf_token'] ?? '')) {        $message = "Invalid request. Refresh the page.";    } else {        $id = filter_input(INPUT_POST, 'subject_id', FILTER_VALIDATE_INT);        if ($id) {            $result = pg_query_params(                $conn,                "DELETE FROM subjects WHERE subject_id = $1",                [$id]            );            $message = ($result && pg_affected_rows($result) > 0)                ? "Subject deleted successfully!"                : "Subject could not be deleted.";        }    }}// GET ALL SUBJECTS$subjects = pg_query(    $conn,    "SELECT s.subject_id, s.subject_name,            s.subject_code, s.semester,            t.teacher_name     FROM subjects s     LEFT JOIN teachers t     ON s.teacher_id = t.teacher_id     ORDER BY s.semester ASC, s.subject_name ASC");function e($value) {    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>SmartAttend | All Subjects</title><style>* {    margin: 0;    padding: 0;    box-sizing: border-box;    font-family: Arial, sans-serif;}body {    background: #f5f7fb;    color: #263653;}/* HEADER */.header {    background: #0875c9;    color: white;    padding: 20px 30px;    display: flex;    justify-content: space-between;    align-items: center;}.brand {    font-size: 23px;    font-weight: bold;}.back-btn {    background: #ffffff;    color: #0875c9;    text-decoration: none;    padding: 11px 18px;    border-radius: 8px;    font-weight: bold;}/* MAIN */.container {    max-width: 1250px;    margin: 40px auto;    padding: 0 25px;}.heading {    margin-bottom: 25px;}.heading h1 {    font-size: 30px;    margin-bottom: 10px;}.heading p {    color: #8993a5;    font-size: 14px;}/* TABLE BOX */.subject-box {    background: white;    padding: 25px;    border-radius: 15px;    box-shadow: 0 5px 20px rgba(0,0,0,0.06);}.message {    margin-bottom: 15px;    color: #16803d;    font-weight: bold;}.table-responsive {    width: 100%;    overflow-x: auto;}table {    width: 100%;    border-collapse: collapse;    min-width: 750px;}th {    background: #eef5fb;    color: #40516b;    padding: 17px 15px;    text-align: left;    font-size: 14px;}td {    padding: 17px 15px;    border-bottom: 1px solid #edf0f4;    font-size: 14px;}tr:hover {    background: #f8fbff;}/* ACTION BUTTONS */.actions {    display: flex;    gap: 8px;    align-items: center;}.edit-btn,.delete-btn {    padding: 8px 12px;    border: none;    border-radius: 6px;    color: white;    text-decoration: none;    cursor: pointer;    font-size: 13px;}.edit-btn {    background: #16a34a;}.delete-btn {    background: #dc2626;}.status {    display: inline-block;    background: #e8f1ff;    color: #1765a5;    padding: 6px 11px;    border-radius: 15px;}/* MOBILE */@media(max-width:600px) {    .header {        padding: 17px;    }    .brand {        font-size: 19px;    }    .back-btn {        padding: 9px 11px;        font-size: 12px;    }    .container {        margin: 25px auto;        padding: 0 13px;    }    .heading h1 {        font-size: 25px;    }    .subject-box {        padding: 15px;    }}</style></head><body><header class="header">    <div class="brand">SmartAttend</div>    <a href="dashboard.php" class="back-btn">        Back to Dashboard    </a></header><div class="container">    <div class="heading">        <h1>All Subjects</h1>        <p>View all registered subject details.</p>    </div>    <div class="subject-box">        <?php if ($message !== ""): ?>            <p class="message"><?php echo e($message); ?></p>        <?php endif; ?>        <div class="table-responsive">            <table>                <tr>                    <th>ID</th>                    <th>Subject Name</th>                    <th>Subject Code</th>                    <th>Semester</th>                    <th>Teacher</th>                    <th>Action</th>                </tr>                <?php if ($subjects && pg_num_rows($subjects) > 0): ?>                    <?php while ($row = pg_fetch_assoc($subjects)): ?>                    <tr>                        <td><?php echo e($row['subject_id']); ?></td>                        <td><?php echo e($row['subject_name']); ?></td>                        <td><?php echo e($row['subject_code']); ?></td>                        <td>                            <span class="status">                                <?php echo e($row['semester']); ?>                            </span>                        </td>                        <td>                            <?php echo e($row['teacher_name'] ?? 'Not Assigned'); ?>                        </td>                        <td>                            <div class="actions">                                <a class="edit-btn"                                   href="edit_subject.php?id=<?php echo (int)$row['subject_id']; ?>">                                    Edit                                </a>                                <form method="POST"                                      onsubmit="return confirm('Delete this subject?');">                                    <input type="hidden"                                           name="csrf_token"                                           value="<?php echo e($_SESSION['subject_csrf']); ?>">                                    <input type="hidden"                                           name="subject_id"                                           value="<?php echo (int)$row['subject_id']; ?>">                                    <button type="submit"                                            name="delete_subject"                                            class="delete-btn">                                        Delete                                    </button>                                </form>                            </div>                        </td>                    </tr>                    <?php endwhile; ?>                <?php else: ?>                    <tr>                        <td colspan="6">No subjects found.</td>                    </tr>                <?php endif; ?>            </table>        </div>    </div></div></body></html>